import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        List<Character> e = new ArrayList<>();
        boolean at = true;
        int len = s.length();

        for (int i = 0; i < len; i++) {
            char x = s.charAt(i);
            if (i >= 2 && i < len - 1) {
                String threeChars = s.substring(i - 2, i + 1);
                if (threeChars.equals("dot")) {
                    e.remove(e.size() - 1);
                    e.remove(e.size() - 1);
                    e.add('.');
                    continue;
                }
            }
            if (i >= 1 && i < len - 1) {
                String twoChars = s.substring(i - 1, i + 1);
                if (twoChars.equals("at") && at) {
                    e.remove(e.size() - 1);
                    e.add('@');
                    at = false;
                    continue;
                }
            }
            e.add(x);
        }

        StringBuilder z = new StringBuilder();
        for (char c : e) {
            z.append(c);
        }
        System.out.println(z.toString());
        scanner.close();
    }
}
